<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { ref, watch } from 'vue';

const props=defineProps({pages:Array,selectedPage:Object,canUpdate:Boolean,canPreview:Boolean,canPublish:Boolean});
const page=usePage();
const sections=ref([]),dragIndex=ref(null);
const hydrate=()=>sections.value=(props.selectedPage?.sections||[]).map(item=>({...item}));
hydrate();watch(()=>props.selectedPage,hydrate);
const form=useForm({version:props.selectedPage?.version,sections:[]});
function move(from,to){if(!props.canUpdate||to<0||to>=sections.value.length)return;const list=[...sections.value],item=list.splice(from,1)[0];list.splice(to,0,item);sections.value=list}
function drop(to){if(dragIndex.value!==null)move(dragIndex.value,to);dragIndex.value=null}
function save(){form.version=props.selectedPage.version;form.sections=sections.value.map(({key,visible})=>({key,visible}));form.put(route('admin.pages.update',props.selectedPage.id),{preserveScroll:true})}
function publishPage(){if(confirm('Publikasikan susunan section ini ke website?'))router.post(route('admin.pages.publish',props.selectedPage.id),{},{preserveScroll:true})}
function discard(){if(confirm('Batalkan seluruh perubahan draft?'))router.post(route('admin.pages.discard',props.selectedPage.id),{},{preserveScroll:true})}
</script>
<template><Head title="Landing Page"/><AuthenticatedLayout><template #page-title>Landing Page</template><div class="page-manager">
<div v-if="page.props.flash?.success" class="notice">{{page.props.flash.success}}</div>
<header class="manager-hero"><div><span>Pengaturan Halaman</span><h1>Kelola Section<b>.</b></h1><p>Atur section yang tampil dan susun urutannya sebelum dipublikasikan.</p></div><div class="hero-status"><i :class="{dirty:selectedPage?.dirty}"></i><div><strong>{{selectedPage?.dirty?'Draft berubah':'Sudah sinkron'}}</strong><small>Versi publik {{selectedPage?.version}}</small></div></div></header>
<div class="workspace">
<aside class="pages"><div class="aside-title">Halaman Website</div><Link v-for="item in pages" :key="item.key" :href="route('admin.pages.index',item.key)" :class="{active:item.key===selectedPage?.key}"><span>{{item.label}}<small>{{item.path}}</small></span><i v-if="item.dirty">Draft</i></Link></aside>
<main v-if="selectedPage" class="editor"><header><div><span>Halaman yang Dikelola</span><h2>{{selectedPage.label}}</h2><p>{{selectedPage.sections.length}} section · Navbar dan footer selalu tampil</p></div><div class="header-actions"><a v-if="canPreview" :href="route('admin.pages.preview',selectedPage.id)" target="_blank">Preview Draft</a><button v-if="canPublish" :disabled="!selectedPage.dirty" class="publish" @click="publishPage">Publikasikan</button></div></header>
<div v-if="selectedPage.dirty" class="draft-bar"><span>● Ada perubahan yang belum diterbitkan</span><button v-if="canUpdate" @click="discard">Batalkan perubahan</button></div>
<div class="section-list"><article v-for="(section,index) in sections" :key="section.key" :class="{hidden:!section.visible,locked:section.locked}" :draggable="canUpdate" @dragstart="dragIndex=index" @dragover.prevent @drop="drop(index)"><div class="handle">⠿</div><div class="position">{{String(index+1).padStart(2,'0')}}</div><div class="section-copy"><strong>{{section.label}}</strong><small>Konten dan tampilan section</small></div><span v-if="section.locked" class="badge">Wajib</span><Link v-if="canUpdate" class="edit-content" :href="route('admin.sections.edit',section.id)">Edit Konten</Link><div class="order"><button :disabled="!canUpdate||index===0" @click="move(index,index-1)">↑</button><button :disabled="!canUpdate||index===sections.length-1" @click="move(index,index+1)">↓</button></div><label class="toggle"><input v-model="section.visible" type="checkbox" :disabled="!canUpdate||section.locked"><span></span><b>{{section.visible?'Tampil':'Sembunyi'}}</b></label></article></div>
<footer class="editor-footer"><div><strong>Versi publik terakhir</strong><small>{{selectedPage.published_at||'Konfigurasi awal'}}<template v-if="selectedPage.publisher"> · {{selectedPage.publisher}}</template></small></div><button v-if="canUpdate" :disabled="form.processing" class="save" @click="save">Simpan Draft</button></footer>
</main></div></div></AuthenticatedLayout></template>
