@media(max-width:850px){.manager-hero{align-items:flex-start;flex-direction:column;justify-content:flex-end}.hero-status{width:100%}.workspace{grid-template-columns:1fr}.pages{display:flex;overflow:auto}.aside-title{display:none}.pages>a{min-width:130px;border-top:0;border-right:1px solid #ffffff12}.section-list article{grid-template-columns:24px 30px 1fr auto}.order{grid-column:3}.toggle{grid-column:4;grid-row:1/3}.badge{display:none}}@media(max-width:520px){.manager-hero{padding:26px 21px}.editor>header{align-items:flex-start;flex-direction:column;gap:15px}.header-actions{width:100%}.header-actions>*{flex:1;text-align:center}.section-list{padding:8px}.section-list article{padding:9px;grid-template-columns:20px 25px 1fr}.section-copy small{display:none}.toggle{grid-column:3;grid-row:2}.order{grid-column:2}.editor-footer{align-items:flex-start;flex-direction:column;gap:14px}.save{width:100%}}
